/** v1: gold + tile position as [x, y] tuple */
export const SaveV1 = z.object({
  v: z.literal(1),
  gold: z.number(),
  pos: z.tuple([z.number(), z.number()]),
});
export type SaveV1 = z.infer<typeof SaveV1>;

/** v2: adds inventory */
export const SaveV2 = z.object({
  v: z.literal(2),
  gold: z.number(),
  pos: z.tuple([z.number(), z.number()]),
  inventory: z.array(z.string()),
});
export type SaveV2 = z.infer<typeof SaveV2>;

/** v3: pos becomes {x,y}; settings with defaulted volume */
export const SaveV3 = z.object({
  v: z.literal(3),
  gold: z.number(),
  pos: z.object({ x: z.number(), y: z.number() }),
  inventory: z.array(z.string()),
  settings: z.object({ volume: z.number().default(0.8) }),
});
export type SaveV3 = z.infer<typeof SaveV3>;

/** v1 -> v2 */
export function migrateV1toV2(save: SaveV1): SaveV2 {
  return { ...save, v: 2, inventory: [] };
}

/** v2 -> v3 */
export function migrateV2toV3(save: SaveV2): SaveV3 {
  return {
    v: 3,
    gold: save.gold,
    pos: { x: save.pos[0], y: save.pos[1] },
    inventory: save.inventory,
    settings: { volume: 0.8 },
  };
}

export class MigrationError extends Error {
  constructor(
    message: string,
    readonly cause?: unknown,
  ) {
    super(message);
    this.name = "MigrationError";
  }
}

/**
 * Parse unknown input with the schema matching its `v` discriminator,
 * then apply stepwise migrations up to the latest version (v3).
 * Throws ZodError if the input doesn't match any known version shape,
 * and MigrationError for unsupported future versions.
 */
export function migrateToLatest(input: unknown): SaveV3 {
  // Peek at the version tag to pick the right schema.
  const peek = z.object({ v: z.number() }).safeParse(input);
  if (!peek.success) {
    throw new MigrationError("missing or invalid version tag `v`", peek.error);
  }

  let current: unknown;
  switch (peek.data.v) {
    case 1:
      current = migrateV1toV2(SaveV1.parse(input));
      break;
    case 2:
      current = SaveV2.parse(input);
      break;
    case 3:
      current = SaveV3.parse(input);
      break;
    default:
      throw new MigrationError(`unsupported save version: ${peek.data.v}`);
  }

  if (peek.data.v !== 3) current = migrateV2toV3(current as SaveV2);
  return SaveV3.parse(current); // belt & braces: output always validates
}
