result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/save.test.ts", "content": "import { describe, expect, it } from "vitest";
import { z } from "zod";
import {
  SaveV1,
  SaveV2,
  SaveV3,
  migrateToLatest,
} from "../src/save.js";

// Deterministic PRNG (mulberry32) so the fuzz test is reproducible.
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const v1Fixture = { v: 1, gold: 250, pos: [12, -7] };
const v2Fixture = { v: 2, gold: 99, pos: [3, 4], inventory: ["sword", "potion"] };
const v3Fixture = {
  v: 3,
  gold: 5,
  pos: { x: 1.5, y: 2.5 },
  inventory: ["key"],
  settings: { volume: 0.4 },
};

const allFixtures = [v1Fixture, v2Fixture, v3Fixture];

describe("migrateToLatest", () => {
  it("accepts each version's schema", () => {
    expect(SaveV1.parse(v1Fixture).gold).toBe(250);
    expect(SaveV2.parse(v2Fixture).inventory).toEqual(["sword", "potion"]);
    expect(SaveV3.parse(v3Fixture).settings.volume).toBe(0.4);
  });

  it("valid fixtures of every version migrate to objects passing SaveV3.parse", () => {
    for (const fixture of allFixtures) {
      const migrated = migrateToLatest(fixture);
      const parsed = SaveV3.parse(migrated); // throws if invalid
      expect(parsed).toEqual(migrated);
      expect(parsed.v).toBe(3);
    }
  });

  it("applies the default volume when migrating older saves", () => {
    expect(migrateToLatest(v1Fixture).settings.volume).toBe(0.8);
    expect(migrateToLatest(v2Fixture).settings.volume).toBe(0.8);
  });

  it("v1 migration equals the exact expected v3 object (deep equal)", () => {
    expect(migrateToLatest(structuredClone(v1Fixture))).toEqual({
      v: 3,
      gold: 250,
      pos: { x: 12, y: -7 },
      inventory: [],
      settings: { volume: 0.8 },
    });
  });

  it("rejects unsupported future versions with MigrationError, not silent success", () => {
    expect(() =>
      migrateToLatest({ ...v3Fixture, v: 4 }),
    ).toThrowError(/unsupported save version/);
  });

  // Fuzz: 200 seeded structurally-broken variants must all be rejected.
  it.fuzz?.("fuzz") ?? it("rejects 200 seeded structurally-broken variants with ZodError", () => {
    const rng = mulberry32(1337);
    let rejectedAsZod = 0;

    for (let i = 0; i < 200; i++) {
      const base = structuredClone(allFixtures[Math.floor(rng() * allFixtures.length)]);
      const keys = Object.keys(base) as (keyof typeof base)[];
      const mode = rng() < 0.5 ? "delete" : "wrongtype";

      if (mode === "delete") {
        delete base[keys[Math.floor(rng() * keys.length)]];
      } else {
        const key = keys[Math.floor(rng() * keys.length)];
        const garbage = [
          "not-a-number",
          null,
          true,
          {},
          [1, 2],
          Number.NaN, // zod rejects NaN for z.number()
        ][Math.floor(rng() * 6)];
        (base as Record<string, unknown>)[key] = garbage;
      }

      let threw: unknown;
      try {
        migrateToLatest(base);
      } catch (e) {
        threw = e;
      }
      expect(threw, `variant #${i} (${mode} ${JSON.stringify(base)}) should be rejected`).toBeDefined();
      expect(threw).toBeInstanceOf(z.ZodError);
      rejectedAsZod++;
    }

    expect(rejectedAsZod).toBe(200);
  });

  it.each([
    [{}, "empty object"],
    [{ v: "1" }, "string version"],
    [{ v: 1 }, "missing gold and pos"],
    [null, "null input"],
    ["save", "string input"],
  ])("rejects %s (%s)", (input) => {
    expect(() => migrateToLatest(input)).toThrow();
  });
});
"})
